import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"PhysGen3D: Crafting a Miniature Interactive World from a Single Image","description":"","frontmatter":{"title":"PhysGen3D: Crafting a Miniature Interactive World from a Single Image","arxiv":"2503.20746","date":"2025-03-26","authors":"Boyuan Chen, Hanxiao Jiang, Shaowei Liu, Saurabh Gupta, Yunzhu Li, Hao Zhao, Shenlong Wang","categories":"cs.CV","topics":"智能体视频生成, 物理仿真, 单图 3D 重建","outline":[2,2]},"headers":[],"relativePath":"papers/2503.20746.md","filePath":"papers/2503.20746.md","lastUpdated":null}'),e={name:"papers/2503.20746.md"};function l(m,s,r,i,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="physgen3d-crafting-a-miniature-interactive-world-from-a-single-image" tabindex="-1">PhysGen3D: Crafting a Miniature Interactive World from a Single Image <a class="header-anchor" href="#physgen3d-crafting-a-miniature-interactive-world-from-a-single-image" aria-label="Permalink to &quot;PhysGen3D: Crafting a Miniature Interactive World from a Single Image&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.20746" target="_blank" rel="noreferrer">2503.20746</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-26（arXiv comments 标注 CVPR 2025；本页依据 HTML v1 全文与附录 A/B/C 撰写）</td></tr><tr><td><strong>作者</strong></td><td>Boyuan Chen, Hanxiao Jiang, Shaowei Liu, Saurabh Gupta, Yunzhu Li, Hao Zhao, Shenlong Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>完全 training-free：用一串预训练感知模型从单张图重建出带 PBR 材质与物理属性的 3D 微缩场景，交给 MPM 仿真器算动力学，再做物理渲染，从而得到可以指定初速度、可重复交互的视频。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型能把一张图变成一段动起来的视频，但你无法告诉它「这个杯子以每秒 2 米向左飞出去」，也无法在同一张图上重跑一遍换个初速度。它生成的是一段像素，而非一个可被操作的世界。</p><p>PhysGen3D 把问题重定义为：从单张图<strong>构造一个微缩的可交互世界</strong>——恢复物体的 3D 几何、位姿、材质与物理属性，恢复支撑面，然后把动力学交给真正的物理仿真器。初速度、角速度、材质硬度因此都成了可显式指定的输入，同一场景可以被反复推演。这把视频生成（输出一段观测）与世界建模（输出一个可查询的状态）拉开了距离。整套方法<strong>不训练任何模型</strong>，全由预训练组件拼装——这既是它最讨巧的地方，也是最脆弱的地方。论文标注录用于 CVPR 2025。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>运动可控的视频生成</strong>（开源基线 DragAnything、MOFA-Video）允许用拖拽轨迹指定运动，把轨迹作为条件注入扩散模型。但轨迹是二维屏幕空间的，模型内部不理解质量、弹性或碰撞，物体穿过桌面或形变不合理无从约束。</p><p><strong>商用大模型</strong>（Kling 1.0、Runway Gen-3、Pika 1.5）画质极高，实验也确认它们的 photorealism 不输给 PhysGen3D，个别还更高。但它们同样不接受物理量作为输入，且每次生成是不可复现的一次性采样。<strong>基于仿真的图像动画化</strong>方法则需要人工搭建 3D 资产与物理参数，无法从任意一张野外照片自动启动。</p><p>因此缺口在于：把「从单图恢复一个物理上自洽的 3D 场景」这整条感知链打通，且不引入新的训练需求。难点不在仿真器（MPM 是成熟技术），而在恢复仿真器需要的<strong>全部</strong>输入——几何、位姿、材质、光照、碰撞面、以及每个物体的密度与杨氏模量。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点是一个朴素观察：物理仿真本身早就够好了，缺的是喂给它的场景。所以问题从「怎么生成物理正确的视频」变成「怎么把一张照片翻译成仿真器的输入文件」。顺着这条逐项清点仿真器需要什么，每一项都有现成预训练模型可用：类别问 GPT-4o，实例分割用 Grounded-SAM，单视图 mesh 用 InstantMesh（内部走 Zero123++），深度用 Dust3r，背景补全用 LaMA，光照用 DiffusionLight，材质用 Mitsuba3 逆渲染。</p><p>真正没有现成模型的是<strong>物理属性</strong>——没有任何视觉模型会告诉你这个陶瓷杯的杨氏模量。作者的选择是继续问 GPT-4o。这里有一个很诚实的实现细节：论文明说因为 GPT 给出的杨氏模量数值<strong>跨好几个数量级不稳定</strong>，才退而求其次改成 soft / medium / hard 三档，在仿真器里分别对应 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">4</span></span></span></span></span></span></span></span><span class="mord">/5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0641em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">5</span></span></span></span></span></span></span></span><span class="mord">/5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span>。这个妥协是全文最值得记住的工程判断，也是 §9 的靶心。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>如果能把一张照片完整翻译成物理仿真器的输入，那么「物理上正确的运动」就不需要被学习，它是仿真器的免费副产品。整个方法的赌注在于：2024–2025 年的预训练感知模型加起来，已经足以完成这次翻译。剩下的工作是把翻译误差压到仿真器不会崩溃、渲染结果不会露馅的程度。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>三个模块：3D world creation、基于 Taichi-Elements 的 MPM 动力学仿真、两遍 shadow mapping 的物理渲染。</p><p><strong>几何与场景</strong>：GPT-4o 定物体类别 → Grounded-SAM 实例分割 → InstantMesh（用 Zero123++）从单视图生成 mesh，多物体互相遮挡时用迭代 inpainting 补全 → Dust3r 估深度得点云 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span>，再用 Bilateral Normal Integration 得碰撞面 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> → LaMA 补背景。阴影处理容易被忽略但很实际：亮度阈值分割出暗区，取包含物体与其阴影的最大连通域，再用<strong>膨胀核 50</strong> 扩一圈后送去 inpaint，否则物体飞走了地上还留着影子。</p><p><strong>位姿</strong>：多视角渲染 mesh，用 SuperGlue 匹配挑出最佳视角，再用 PnP 解位姿（存在尺度歧义），然后同时调整尺度与平移以最小化 L2 误差；精配准阶段改用可微渲染，最小化 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">dice</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">depth</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>。</p><p><strong>外观与物性</strong>：Mitsuba3 逆渲染估 PBR 参数（albedo / roughness / metallic，后两者每物体取常数），DiffusionLight 估环境光照；albedo 用三次多项式做 tone mapping，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">a</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">b</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">c</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">d</span></span></span></span>，约束 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mopen">(</span><span class="mord">0</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mopen">(</span><span class="mord">1</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。物性则向 GPT-4o 询问密度（kg/m³）、杨氏模量三档、物体尺寸（m）、是否需要内部填充，以及支撑面 roughness（0 到 1）。</p><p><strong>一次完整走法</strong>：给一张桌上放着水果的照片 → 分割出每个水果与桌面 → 各自生成 mesh 并对齐回原图位姿 → 估出 albedo 与桌面粗糙度 → 问 GPT-4o 得到苹果密度约 800 kg/m³、medium 硬度 → 用户指定一个苹果的初速度 → MPM 前向仿真，苹果滚下桌沿撞到另一个 → 物理渲染出视频，阴影随物体移动。VEnhancer 可作为可选后处理提画质。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p><strong>MPM 的连续介质方程</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2173em;vertical-align:-0.345em;"></span><span class="mord mathnormal">ρ</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8723em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">D</span><span class="mord mathnormal mtight">t</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">D</span><span class="mord mathbf mtight" style="margin-right:0.016em;">v</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">∇</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">σ</span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf" style="margin-right:0.109em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.109em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ext</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>。直觉上这就是连续体版本的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ma</span></span></span></span>：左边是质量乘加速度，右边是应力的散度（材料内部相邻部分互相推挤的净力）加外力。</p><p><strong>本构关系</strong>决定材料的软硬：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4444em;"></span><span class="mord"><span class="mord"><span class="mord boldsymbol" style="margin-right:0.037em;">σ</span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">2</span><span class="mord mathnormal">μ</span><span class="mopen">(</span><span class="mord mathbf">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1413em;vertical-align:-0.25em;"></span><span class="mord mathbf">R</span><span class="mclose">)</span><span class="mord"><span class="mord mathbf">F</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">λ</span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord mathbf">I</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">λ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2963em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span><span class="mclose">)</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">2</span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">μ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.2963em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">2</span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0637em;">ν</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">F</span></span></span></span> 是形变梯度，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">R</span></span></span></span> 是它极分解出的旋转部分，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0962em;">J</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mop">det</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">F</span></span></span></span> 是体积变化率。第一项惩罚<strong>形状</strong>改变（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7694em;vertical-align:-0.0833em;"></span><span class="mord mathbf">F</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">R</span></span></span></span> 把纯旋转扣掉，剩下的才是真形变），第二项惩罚<strong>体积</strong>改变。所以 GPT-4o 给出的那个三档 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 直接决定了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>，也就直接决定了物体撞上去是弹开、瘫软还是碎裂。</p><p><strong>量纲缩放</strong>是这套方法能跑起来的关键工程技巧。仿真器里场景边长固定为 2、网格分辨率 256，而真实场景可能是 0.5 米也可能是 5 米。设缩放比 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mord">/</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，则 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9463em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">9.8</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0106em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4413em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>——重力随长度尺度<strong>正比</strong>放大、杨氏模量<strong>反比</strong>缩小，这样物体在仿真世界里的相对形变才与真实世界一致。忘掉这一步的后果是同样的材料在小场景里显得过硬、在大场景里显得过软。p2g 与 g2p 的具体格式见附录 A.4。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>人眼觉得哪个更符合物理？</strong> Table 1 是一次人类研究：<strong>27 条视频、31 名参与者、五点量表</strong>，评 PhysReal / PhotoReal / Align。Kling 1.0 得 2.811 / 3.566 / 2.467，Gen-3 得 2.283 / 3.582 / 1.886，Pika 1.5 得 2.412 / 3.314 / 2.016，PhysGen3D 得 <strong>3.707 / 3.411 / 3.866</strong>。物理真实感与语义对齐大幅领先，但 <strong>PhotoReal 反而低于 Kling 与 Gen-3</strong>，论文没有掩饰。</p><p><strong>自动指标怎么说？</strong> Table 2 用 VBench 加 GPT-4o（gpt-4o-2024-08-06，均匀采样 10 帧）评 Motion / Imaging / PhysReal / PhotoReal / Align。Kling 0.996 / 0.671 / 0.563 / 0.874 / 0.596，Gen-3 0.991 / 0.723 / 0.141 / 0.896 / 0.144，Pika 0.994 / 0.671 / 0.544 / 0.863 / 0.563，MOFA-Video 0.994 / 0.634 / 0.384 / 0.764 / 0.304，DragAnything 0.985 / 0.428 / 0.645 / 0.756 / 0.380，PhysGen3D <strong>0.995 / 0.666 / 0.752 / 0.867 / 0.796</strong>，接 VEnhancer 后 0.994 / 0.677 / 0.766 / 0.880 / 0.745。</p><p>这里有一个方法论上值得表扬的细节：作者在给 GPT-4o 的评测 prompt 里<strong>明确要求惩罚完全静止的视频</strong>。一段什么都不动的视频在 motion smoothness 与 subject consistency 上会拿满分，显式排除 no-op 是很多同类工作没做的。</p><p><strong>哪些模块是必需的？</strong> 消融给出三条：去掉位姿优化，物体只能大致回到原位，与原图对不齐；去掉逆纹理估计，色调与亮度对不上；<strong>不做点采样，大量点挤进同一个 MPM 网格，仿真器直接崩溃</strong>。第三条说明这是能不能跑通的硬约束而非可选项。</p><p><strong>论文自陈的 limitation</strong>：只面向 object-centric 场景与简单空间几何；只支持单一碰撞面；每个物体的密度与弹性假设均匀；MPM 处理细长结构（论文举例：水壶把手）会失败；极端光照下渲染出错；车漆这类强反射材质的逆渲染失败。<strong>应用</strong>：相机控制、稠密 3D tracking、从画作生成视频、材质替换（沙化或融化）。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：PhysGen3D 不训练任何模型，用一串预训练感知模型把单张图翻译成 MPM 仿真器的完整输入。物理属性没有现成模型，改由 GPT-4o 回答，且因数值不稳而退化成 soft / medium / hard 三档。量纲缩放（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9463em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>）是让仿真在归一化场景里保持真实感的关键一步。人评上 PhysReal 3.707 与 Align 3.866 大幅超过 Kling / Gen-3 / Pika，但 PhotoReal 3.411 反而略低。消融显示点采样不是优化项而是不做就崩溃的必需项。</p><p><strong>3 句话版</strong>：把物理正确性从「学出来」改成「算出来」，代价是必须把整张图完整翻译成仿真器输入。翻译链条上每一环都用现成模型，唯独物理属性靠 LLM 猜。结果是物理与语义大幅领先、画质略输商用模型。</p><p><strong>1 句话版</strong>：仿真器不需要被教会物理，需要被喂对场景——本文证明预训练感知模型已经勉强够用。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>假设：GPT-4o 能给出足够准确的物理属性（密度、杨氏模量）。</strong> 整条 pipeline 的其他环节都有几何或光度上的自监督信号可以校验——位姿有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">dice</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">depth</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>、材质有逆渲染重建误差、深度有 Dust3r 的多视图一致性。唯独物理属性<strong>没有任何来自图像的约束</strong>：一个塑料苹果和一个真苹果在照片里长得一样，撞上去的行为完全不同。核心 claim 是输出物理上正确的动力学，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 直接进入本构关系与运动方程，猜错就是全错。</p><p>论文自己提供了最强反证：正文明说因为 GPT 给的杨氏模量<strong>跨好几个数量级不稳定</strong>，才改用三档离散化。这个补救说明作者知道数值不可信，但三档只是把方差换成了偏差——真实材料的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 从橡胶（约 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">7</span></span></span></span></span></span></span></span></span></span></span> Pa）到钢（约 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">11</span></span></span></span></span></span></span></span></span></span></span></span> Pa），而三档只覆盖 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span> 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span>。</p><p>论文缺的关键证据是：没有报告在已知材质的物体上 GPT-4o 的三档分类准确率，也没有报告最终视频评分对这三档的敏感度。若结果对档位不敏感，说明这一环其实没起作用（物理正确的功劳应归于几何与碰撞面）；若高度敏感，那么分类错误率就直接等于失败率。两种情况都需要数据，而两个数据都没有。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要复现完整 pipeline：取 30 到 50 张常见物体照片（覆盖玻璃、陶瓷、塑料、金属、橡胶、水果、织物），其材质有明确的教科书 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 可查；用论文描述的 prompt 向 GPT-4o 询问密度与三档，各问 5 次；测三件事——<strong>档位分类准确率</strong>（对照按教科书 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 映射到三档的 ground truth）、<strong>5 次询问的自一致率</strong>、密度的相对误差分布。再取其中 10 个物体，固定其余环节，只把档位换成另外两档各跑一次，让 10 名标注者做三选一「哪个更像真的」。</p><p>判据：若分类准确率显著高于随机（33%）且人评对档位敏感，则该假设成立且这一环有效；若准确率接近随机，或人评对档位不敏感，则论文的物理正确性应重新归因到几何与碰撞面重建。<strong>这个实验的价值在于它先校准了 GPT-4o 这个自动物性标注器，而论文本身没有做任何校准。</strong></p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>可预测的失败条件（论文自陈但未量化）</strong>：细长结构。MPM 用固定分辨率 256 的欧拉网格，水壶把手、椅子腿、眼镜框这类结构的横截面可能只占一两个网格，粒子间的应力传递失真，行为必然错误。构造一个细长结构测试集（马克杯、剪刀、台灯、自行车），若 PhysReal 在该子集上跌到基线水平以下，那么「物理正确」就只在圆胖物体上成立，而这恰恰是最容易的一类。</p><p><strong>替代解释一：人评的 PhysReal 可能在测视觉风格而非物理。</strong> PhysGen3D 的输出经过物理渲染，观感接近游戏引擎；扩散模型的输出更像实拍。评审很可能把「看起来像仿真」当作「物理正确」的线索。攻击设计：把真实拍摄的碰撞视频、PhysGen3D 输出、以及<strong>故意用错误物理参数</strong>（把陶瓷设成 soft）的 PhysGen3D 输出三者混在一起，用同一份问卷评 PhysReal。若错误参数版本与正确版本无显著差异，那么 3.707 度量的是渲染风格。</p><p><strong>替代解释二：论文自己给出的 trade-off。</strong> Ours + VEnhancer 的 PhotoReal 从 0.867 升到 0.880、Imaging 从 0.666 升到 0.677，但 Align 从 0.796 掉到 0.745。接一层扩散后处理能提画质但引入与原始语义不符的幻觉。反对者可据此论证：PhysGen3D 与商用模型的差距在两个正交维度上，把两者叠加并不能同时拿到两边的优势，「先仿真后增强」这条路存在结构性冲突。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动它的局限</strong>：物理属性靠单帧图像加 LLM 先验猜测，且假设每个物体内部均匀、场景只有单一碰撞面。这三条把方法锁在「桌面上的圆胖物体」这个很窄的域里。</p><p><strong>(b) 可借鉴的相邻领域</strong>：系统辨识（system identification）与可微仿真。既然 MPM 前向过程可以做成可微的，物理属性就不该被「问出来」，而该<strong>从观测中反解出来</strong>：给定一段真实视频（哪怕只有几帧运动），把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>、摩擦系数作为待优化变量，最小化仿真轨迹与观测轨迹的差距。这把问题从 LLM 常识问答变成逆问题求解，也带来了可验证性。</p><p><strong>(c) 第一个实验</strong>：录制一个小规模数据集，每段视频是一个已知材质的物体从固定高度落到桌面并弹起，同时用高速相机记录轨迹（可获得 ground truth 恢复系数）。第一步先做<strong>平凡基线</strong>：直接用教科书查表值跑仿真，看轨迹误差是多少——任何学习方法必须显著优于查表才有意义。第二步跑可微仿真反解，比较三者（GPT-4o 三档 / 查表 / 反解）在留出帧上的轨迹预测误差。第三步只用<strong>第一次弹跳</strong>的观测反解参数，预测第二、第三次弹跳，看外推能撑多久——这个曲线会告诉我们均匀材质假设在什么时候崩掉。</p>',52)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
